{"file_path":"/tmp/claude-0/-home-user-deepseek-harness/f53f80cc-1f77-5d02-a862-99d59ffabdce/scratchpad/bench/runs/e1-haiku-vs-sonnet-t5/cell-yETTF8/src/address.js","content":"// Address helpers: columns run A..Z, AA..ZZ (base-26, no zero digit),
// rows are 1..999.

export function colLettersToNumber(letters) {
  let n = 0
  for (const ch of letters.toUpperCase()) {
    n = n * 26 + (ch.charCodeAt(0) - 64)
  }
  return n
}

export function colNumberToLetters(n) {
  let s = ''
  while (n > 0) {
    const rem = (n - 1) % 26
    s = String.fromCharCode(65 + rem) + s
    n = Math.floor((n - 1) / 26)
  }
  return s
}

// Splits a bare word (letters followed by digits, as produced by the
// tokenizer) into its letters/digits parts. Returns null if the word does
// not have that shape (shouldn't happen given the tokenizer, but defensive).
export function splitWord(word) {
  const m = /^([A-Za-z]+)([0-9]*)$/.exec(word)
  if (!m) return null
  return { letters: m[1], digits: m[2] }
}

// Determines whether letters/digits form an address inside the addressable
// range: 1-2 letters, 1-3 digits naming a row >= 1.
export function isAddressableParts(letters, digits) {
  if (letters.length < 1 || letters.length > 2) return false
  if (digits.length < 1 || digits.length > 3) return false
  const row = parseInt(digits, 10)
  if (!(row >= 1 && row <= 999)) return false
  const col = colLettersToNumber(letters)
  if (!(col >= 1 && col <= 702)) return false
  return true
}

// Validates a full token (e.g. from the sheet header) as a strict address.
// Returns the canonical upper-cased address string, or null if invalid.
export function canonicalAddress(token) {
  const m = /^([A-Za-z]{1,2})([0-9]{1,3})$/.exec(token)
  if (!m) return null
  const letters = m[1].toUpperCase()
  const digits = m[2]
  if (!isAddressableParts(letters, digits)) return null
  return letters + String(parseInt(digits, 10))
}

export function addressParts(addr) {
  const m = /^([A-Za-z]{1,2})([0-9]+)$/.exec(addr)
  return { letters: m[1].toUpperCase(), row: parseInt(m[2], 10) }
}

export function makeAddress(letters, row) {
  return letters.toUpperCase() + String(row)
}

// Compares two canonical addresses by column then row.
export function compareAddresses(a, b) {
  const pa = addressParts(a)
  const pb = addressParts(b)
  const ca = colLettersToNumber(pa.letters)
  const cb = colLettersToNumber(pb.letters)
  if (ca !== cb) return ca - cb
  return pa.row - pb.row
}
"}

