{"file_path":"/tmp/claude-0/-home-user-deepseek-harness/f53f80cc-1f77-5d02-a862-99d59ffabdce/scratchpad/bench/runs/e1-haiku-vs-sonnet-t5/cell-yETTF8/src/lexer.js","content":"// Tokenizer for formula bodies (the text after the leading '=').

const MULTI_OPS = ['<=', '>=', '<>']
const SINGLE_OPS = ['^', '*', '/', '+', '-', '=', '<', '>']

export function tokenize(src) {
  const tokens = []
  let i = 0
  const n = src.length
  while (i < n) {
    const ch = src[i]
    if (ch === ' ' || ch === '\t') {
      i++
      continue
    }
    if (ch === '(') {
      tokens.push({ type: 'LPAREN' })
      i++
      continue
    }
    if (ch === ')') {
      tokens.push({ type: 'RPAREN' })
      i++
      continue
    }
    if (ch === ',') {
      tokens.push({ type: 'COMMA' })
      i++
      continue
    }
    if (ch === ':') {
      tokens.push({ type: 'COLON' })
      i++
      continue
    }
    // number: digits with optional . and more digits, no sign
    if (/[0-9]/.test(ch)) {
      const m = /^[0-9]+(\.[0-9]+)?/.exec(src.slice(i))
      tokens.push({ type: 'NUMBER', value: m[0] })
      i += m[0].length
      continue
    }
    // word: letters followed by optional digits
    if (/[A-Za-z]/.test(ch)) {
      const m = /^[A-Za-z]+[0-9]*/.exec(src.slice(i))
      tokens.push({ type: 'WORD', value: m[0] })
      i += m[0].length
      continue
    }
    let matched = false
    for (const op of MULTI_OPS) {
      if (src.startsWith(op, i)) {
        tokens.push({ type: 'OP', value: op })
        i += op.length
        matched = true
        break
      }
    }
    if (matched) continue
    if (SINGLE_OPS.includes(ch)) {
      tokens.push({ type: 'OP', value: ch })
      i++
      continue
    }
    // Unrecognized character: signal a lexical failure via a special token.
    tokens.push({ type: 'INVALID', value: ch })
    i++
  }
  tokens.push({ type: 'EOF' })
  return tokens
}
"}

