export class SheetError extends Error {
  constructor(message) {
    super(message)
  }
}

// Parses the raw sheet text into a Map from canonical address to raw
// content string. Throws SheetError on the first invalid line.
export function parseSheet(input) {
  let lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') {
    lines = lines.slice(0, -1)
  }
  const cells = new Map()
  for (let idx = 0; idx < lines.length; idx++) {
    const lineNo = idx + 1
    const raw = lines[idx]
    const stripped = raw.replace(/^[ \t]+/, '')
    if (stripped === '' || stripped.startsWith('#')) continue
    const m = /^(\S+)(?:[ \t]+(.*))?$/.exec(stripped)
    // stripped is non-empty and has no leading whitespace, so this always matches
    const addrToken = m[1]
    const content = m[2] === undefined ? '' : m[2]
    const upperToken = addrToken.toUpperCase()
    const addr = canonicalAddress(upperToken)
    if (addr === null) {
      throw new SheetError(`error: line ${lineNo}: invalid cell address ${upperToken}`)
    }
    if (cells.has(addr)) {
      throw new SheetError(`error: line ${lineNo}: cell ${addr} is declared twice`)
    }
    cells.set(addr, content)
  }
  return cells
}
"}

