export const ERROR_TOKENS = ['#DIV/0!', '#REF!', '#VALUE!', '#CYCLE!', '#NAME?', '#ERR!']

export function mkNum(v) {
  return { t: 'num', v }
}
export function mkText(v) {
  return { t: 'text', v }
}
export function mkBool(v) {
  return { t: 'bool', v }
}
export function mkErr(v) {
  return { t: 'err', v }
}

const LITERAL_NUMBER_RE = /^-?[0-9]+(\.[0-9]+)?$/

export function parseLiteral(content) {
  if (content === '') return mkNum(0)
  if (LITERAL_NUMBER_RE.test(content)) return mkNum(parseFloat(content))
  if (ERROR_TOKENS.includes(content)) return mkErr(content)
  return mkText(content)
}

// Coerces a value to a number for arithmetic. Returns either a number
// value or an error value (#VALUE! for text, or the propagated error).
export function coerceNumber(val) {
  if (val.t === 'err') return val
  if (val.t === 'num') return val
  if (val.t === 'bool') return mkNum(val.v ? 1 : 0)
  return mkErr('#VALUE!')
}

// Coerces a value to a boolean for conditions.
export function coerceBool(val) {
  if (val.t === 'err') return val
  if (val.t === 'bool') return val
  if (val.t === 'num') return mkBool(val.v !== 0)
  return mkErr('#VALUE!')
}

function rank(val) {
  if (val.t === 'num') return 0
  if (val.t === 'text') return 1
  if (val.t === 'bool') return 2
  return 3
}

// Total order comparator used for comparison operators. Values must not be
// errors (callers handle error propagation separately).
export function compareValues(a, b) {
  const ra = rank(a)
  const rb = rank(b)
  if (ra !== rb) return ra - rb
  if (a.t === 'num') return a.v - b.v
  if (a.t === 'text') return a.v < b.v ? -1 : a.v > b.v ? 1 : 0
  if (a.t === 'bool') return (a.v ? 1 : 0) - (b.v ? 1 : 0)
  return 0
}
