// Resolves a formula "word" token to a canonical address, or null if it
// falls outside the addressable range.
export function resolveWord(word) {
  const parts = splitWord(word)
  if (!parts || !isAddressableParts(parts.letters, parts.digits)) return null
  return makeAddress(parts.letters, parseInt(parts.digits, 10))
}

// Resolves a range's two corner words into an ordered list of addresses
// (ascending column, then ascending row), regardless of which corner each
// word named. Returns null if either corner is outside the addressable
// range.
export function resolveRange(startWord, endWord) {
  const start = resolveWord(startWord)
  const end = resolveWord(endWord)
  if (start === null || end === null) return null
  const sp = /^([A-Z]{1,2})([0-9]+)$/.exec(start)
  const ep = /^([A-Z]{1,2})([0-9]+)$/.exec(end)
  const c1 = colLettersToNumber(sp[1])
  const c2 = colLettersToNumber(ep[1])
  const r1 = parseInt(sp[2], 10)
  const r2 = parseInt(ep[2], 10)
  const minC = Math.min(c1, c2)
  const maxC = Math.max(c1, c2)
  const minR = Math.min(r1, r2)
  const maxR = Math.max(r1, r2)
  const addrs = []
  for (let c = minC; c <= maxC; c++) {
    const letters = colNumberToLetters(c)
    for (let r = minR; r <= maxR; r++) {
      addrs.push(makeAddress(letters, r))
    }
  }
  return addrs
}
"}

