// Compiles the raw cell contents map into a map from address to either
// { kind: 'literal', content } or { kind: 'formula', ok, ast }.
export function compileSheet(cells) {
  const compiled = new Map()
  for (const [addr, content] of cells) {
    if (content.startsWith('=')) {
      const result = parseFormula(content.slice(1))
      if (result.ok) {
        compiled.set(addr, { kind: 'formula', ok: true, ast: result.ast })
      } else {
        compiled.set(addr, { kind: 'formula', ok: false })
      }
    } else {
      compiled.set(addr, { kind: 'literal', content })
    }
  }
  return compiled
}
