/**
 * The command. `node src/cli.js values` prints the value of every cell in the
 * sheet read from standard input, and `node src/cli.js deps` prints the cells
 * each one reads.
 */

import { parseSheet, SheetError } from './sheet-parser.js'
import { compileSheet } from './compile.js'
import { evaluateSheet } from './evaluate.js'
import { directDeps } from './deps.js'
import { formatValue } from './format.js'
import { compareAddresses } from './address.js'

function readStdin() {
  const fs = require('node:fs')
  return fs.readFileSync(0, 'utf8')
}

async function main() {
  const args = process.argv.slice(2)
  if (args.length !== 1 || (args[0] !== 'values' && args[0] !== 'deps')) {
    process.stderr.write('error: usage: cli.js values|deps\n')
    process.exit(2)
  }
  const mode = args[0]

  const chunks = []
  process.stdin.on('data', (c) => chunks.push(c))
  await new Promise((resolve) => process.stdin.on('end', resolve))
  const input = Buffer.concat(chunks).toString('utf8')

  let cells
  try {
    cells = parseSheet(input)
  } catch (e) {
    if (e instanceof SheetError) {
      process.stderr.write(e.message + '\n')
      process.exit(2)
    }
    throw e
  }

  const compiled = compileSheet(cells)
  const addrs = Array.from(cells.keys()).sort(compareAddresses)

  let out = ''
  if (mode === 'values') {
    const values = evaluateSheet(compiled)
    for (const addr of addrs) {
      out += `${addr}=${formatValue(values.get(addr))}\n`
    }
  } else {
    for (const addr of addrs) {
      const deps = directDeps(compiled.get(addr))
      out += `${addr}:${deps.map((d) => ' ' + d).join('')}\n`
    }
  }
  process.stdout.write(out)
  process.exit(0)
}

main()
"}

